  function feedKind(kind,changes=[]){const fields=new Set(changes.map(row=>row.field));if(fields.has('created'))return '新增节点';if(fields.has('deleted'))return '删除节点';return ({direct_edit:'更新节点',status_toggle:'切换状态',undo:'撤销提交',initial_correction:'纠正初始日期',import:'导入项目'})[kind]||kind||'更新'}
